//! Immutable notification endpoint inputs and bounded delivery metadata.
use crate::ProviderDestinationPolicy;
use serde::{Deserialize, Serialize};
use time::OffsetDateTime;
use uuid::Uuid;

/// Owner-authorized destination; signing secret is generated by the server.
#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ApplicationNotificationEndpointRequest {
    /// Exact owner operation key.
    pub idempotency_key: String,
    /// Reason recorded in the immutable audit.
    pub reason: String,
    /// Exact immutable destination without query, fragment or user information.
    pub url: String,
    /// Public HTTPS by default; internal IPs require explicit owner configuration.
    #[serde(default)]
    pub destination_policy: ProviderDestinationPolicy,
    /// Explicit subscribed lifecycle signal types.
    pub events: Vec<String>,
}
/// One exact disable/retry intent.
#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ApplicationNotificationMutation {
    /// Exact owner operation key.
    pub idempotency_key: String,
    /// Audited reason.
    pub reason: String,
}
/// Safe endpoint metadata; no signing or sealing material.
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ApplicationNotificationEndpoint {
    /// Stable endpoint identity.
    pub endpoint_id: Uuid,
    /// Owning application.
    pub application_id: Uuid,
    /// Immutable approved URL.
    pub url: String,
    /// Immutable exact destination policy.
    pub destination_policy: ProviderDestinationPolicy,
    /// Subscribed event types.
    pub events: Vec<String>,
    /// Whether new enqueue and unclaimed delivery are enabled.
    pub enabled: bool,
    /// Recognition suffix; never enough to sign.
    pub secret_last4: String,
    /// Creation instant.
    #[serde(with = "time::serde::rfc3339")]
    pub created_at: OffsetDateTime,
}
/// First creation reveals signing material once; retry reveals metadata only.
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CreatedApplicationNotificationEndpoint {
    /// Stable endpoint metadata.
    pub endpoint: ApplicationNotificationEndpoint,
    /// Available only on first successful creation.
    pub secret: Option<String>,
}
/// At most twenty retained endpoint identities.
#[derive(Serialize)]
pub struct ApplicationNotificationEndpoints {
    /// Safe endpoint metadata.
    pub endpoints: Vec<ApplicationNotificationEndpoint>,
}
/// Bounded delivery status; body is sent only to the approved endpoint.
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ApplicationNotificationDelivery {
    /// Stable receiver deduplication identity.
    pub delivery_id: Uuid,
    /// Destination identity.
    pub endpoint_id: Uuid,
    /// Exact customer whose current state may have changed.
    pub organization_id: Uuid,
    /// Lifecycle signal type, not a monotonic state projection.
    pub event_type: String,
    /// Current resource to reconcile.
    pub entity_id: Uuid,
    /// Durable delivery state.
    pub status: String,
    /// Attempts in the current automatic retry cycle.
    pub attempts: i32,
    /// Next automatic attempt time.
    #[serde(with = "time::serde::rfc3339")]
    pub next_attempt_at: OffsetDateTime,
    /// Last HTTP response status, if any.
    pub response_status: Option<i32>,
    /// Sanitized category; no URL, receiver response or signing secret.
    pub last_error: Option<String>,
    /// Immutable enqueue time.
    #[serde(with = "time::serde::rfc3339")]
    pub created_at: OffsetDateTime,
    /// Last successful delivery time.
    #[serde(with = "time::serde::rfc3339::option")]
    pub delivered_at: Option<OffsetDateTime>,
    /// Internal lease fence, excluded from HTTP.
    #[serde(skip)]
    pub(crate) claimed_at: Option<OffsetDateTime>,
}
/// Bounded ascending-identity delivery page.
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ApplicationNotificationDeliveries {
    /// At most fifty statuses.
    pub deliveries: Vec<ApplicationNotificationDelivery>,
    /// Last returned identifier if another page exists.
    pub next_cursor: Option<Uuid>,
}
/// Internal worker material, never serialized as an HTTP response.
pub struct DueApplicationNotification {
    /// Lease-owned delivery.
    pub delivery: ApplicationNotificationDelivery,
    /// Exact immutable destination.
    pub url: String,
    /// Validated policy for that destination.
    pub destination_policy: ProviderDestinationPolicy,
    /// Sealed signing material.
    pub secret_sealed: String,
    /// Original bytes signed and sent on every retry.
    pub body: String,
}
